T=np.array(G['Test input']); H,W=T.shape
# Find ALL maximal rectangles (contiguous 0 border enclosing interior with a 1). Use "closed shape" approach.
# A closed rectangle: all four sides fully 0, corners 0, and interior cells are not part of other boxes' borders.
def is_closed(y1,y2,x1,x2):
    if T[y1,x1:x2+1][0].tolist() or True: pass
    return all(v==0 for v in T[y1,x1:x2+1]) and all(v==0 for v in T[y2,x1:x2+1]) and all(T[y,x1]==0 for y in range(y1,y2+1)) and all(T[y,x2]==0 for y in range(y1,y2+1))
maxboxes=[]
for y1 in range(H-1):
    for x1 in range(W-1):
        if T[y1,x1]!=0: continue
        for y2 in range(y1+1,H):
            if T[y2,x1]!=0 or T[y2,x1+1]!=0: break
            for x2 in range(x1+1,W):
                if not is_closed(y1,y2,x1,x2): continue
                inter=T[y1+1:y2,x1+1:x2]
                if inter.size<=3: continue
                maxboxes.append((y1,y2,x1,x2,int((inter==1).sum()),sorted(set(inter.flatten().tolist()))))
print(len(maxboxes))
for c in maxboxes: print(c)

