            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def find_frames(D,bg):
    D=np.array(D); H,W=D.shape; res=[]
    for bc in set(D.flatten().tolist())-{bg}:
        for y1 in range(H):
            for x1 in range(W):
                if D[y1,x1]!=bc: continue
                for y2 in range(y1+1,H):
                    if D[y2,x1]!=bc: break
                    for x2 in range(x1+1,W):
                        if not ((D[y1,x1:x2+1]==bc)&(D[y2,x1:x2+1]==bc)).all(): continue
                        if not ((D[y1:y2+1,x1]==bc)&(D[y1:y2+1,x2]==bc)).all(): continue
                        inter=D[y1+1:y2,x1+1:x2]
                        nz=int((inter!=bg).sum())
                        if nz>0: res.append((bc,(y1,y2,x1,x2),nz,inter.copy()))
    return res

def f(D):
    D=np.array(D); vals,cnts=np.unique(D,return_counts=True); bg=int(vals[np.argmax(cnts)])
    cands=find_frames(D,bg)
    # choose frame with max noise count, tie-break largest area then... use first by noise desc
    cands.sort(key=lambda c:-c[2])
    _,(y1,y2,x1,x2),nz,inter=cands[0]
    nonbg=set(int(v) for v in inter.flatten())-{bg}
    ncol=nonbg.pop() if nonbg else None
    nh,nw=inter.shape
    out=np.full((nh+2,nw+2),ncol,dtype=int)
    out[1:nh+1,1:nw+1]=inter
    return out.tolist()

